import { createSignal, Suspense } from 'solid-js';
import HeavyTab from './HeavyTab';

// ❌ OLD: Clicking the button immediately triggers the Suspense fallback,
// hiding the current tab and showing a jarring loading spinner.
export default function TabContainer() {
  const [tab, setTab] = createSignal('home');

  return (
    <div>
      <button onClick={() => setTab('heavy')}>Open Heavy Tab</button>
      <Suspense fallback={<div className="spinner">Loading full tab...</div>}>
        {tab() === 'home' ? <Home /> : <HeavyTab />}
      </Suspense>
    </div>
  );
}

import { createSignal, useTransition, Suspense } from 'solid-js';
import HeavyTab from './HeavyTab';

// ✅ NEW: useTransition keeps <Home /> visible while <HeavyTab /> loads data in the background.
export default function TabContainer() {
  const [tab, setTab] = createSignal('home');
  const [pending, start] = useTransition();

  return (
    <div>
      <button
        disabled={pending()}
        onClick={() => {
          // Keeps Home visible until HeavyTab finishes fetching!
          start(() => setTab('heavy'));
        }}
      >
        Open Heavy Tab {pending() && '(Loading...)'}
      </button>

      <div style={{ opacity: pending() ? 0.6 : 1.0 }}>
        <Suspense fallback={<div className="spinner">Initial load only...</div>}>
          {tab() === 'home' ? <Home /> : <HeavyTab />}
        </Suspense>
      </div>
    </div>
  );
}
